import math

def mod_expo(a, b, m):
	if b == 0:
		return (1 % m)
	ans = mod_expo(a, b//2, m)
	if b % 2 == 0:
		return (ans * ans) % m
	else:
		return (ans * ans * (a % m)) % m

def mat_mul(mat1, mat2, m):
	ans = [[0,0],[0,0]]
	ans[0][0] = (mat1[0][0]*mat2[0][0] + mat1[0][1]*mat2[1][0])%m
	ans[0][1] = (mat1[0][0]*mat2[0][1] + mat1[0][1]*mat2[1][1])%m
	ans[1][0] = (mat1[1][0]*mat2[0][0] + mat1[1][1]*mat2[1][0])%m
	ans[1][1] = (mat1[1][0]*mat2[0][1] + mat1[1][1]*mat2[1][1])%m
	return ans

def mod_mat_expo(mat, n, m):
	if n == 0:
		return [[1 % m, 0],[0, 1 % m]]
	ans = mod_mat_expo(mat, n//2, m)
	ans = mat_mul(ans, ans, m)
	if n % 2 == 0:
		return ans
	else:
		return mat_mul(ans, mat, m)

def f(n, m):
	if n == 2:
		return 3 % m
	if n == 3:
		return 5 % m
	mat = [[1,1],[1,0]]
	mat = mod_mat_expo(mat, n-3, m)
	return (mat[0][0]*(5%m)+mat[0][1]*(3%m))%m

