from collections import defaultdict
def primeFactors(n):
    factors = []
    while n%2==0:
        factors.append(2)
        n = n//2

    k = 3
    while k <= math.sqrt(n):
        if n%k==0:
            n= n//k
            factors.append(k)
        else:
            k+=2
    if n>1:
        factors.append(n)
    return factors

