class Solution:




    @staticmethod
    def bookreading(pages , firstday , threshold , addingFactor , gobackPages):
        pages = pages-firstday
        day = 1
        while pages>0:
            pages = pages+gobackPages

            factor = firstday+day*addingFactor
            if factor  <= threshold:
                pages_read = factor
            pages = pages - pages_read

            day += 1


        return day



