def binary_search(a, lo=0, hi=None):
    if hi is None:
        hi = len(a)
    while lo < hi:
        mid = (lo+hi)//2
        midval = a[mid]
        if midval > 0:
            lo = mid+1
        elif midval < 0:
            hi = mid
        else:
            return mid
    return lo

