class Primos:

    def __init__(self, MAX):
        self.Max=MAX
        self.primos=[True]*(MAX+1)
        self.ListPrimes=[]

        for i in xrange(2,int(MAX**0.5)+1):
            if self.primos[i]:
                for j in xrange(i*i,self.Max+1,i):
                    self.primos[j]=False
        #Listing primes

        for p in range(2,MAX+1):
            if self.primos[p]: self.ListPrimes.append(p)


    def esPri(self,n):
        return self.primos[n]

    def Primorial(self, N):
    	pri=1
    	for i in xrange(N):
    		pri*=self.getPrimesList()[i]
    	return pri

    def PrimeFactors(self, N):
    	d={}
    	for i in xrange(2, N/2+1):
    		if self.esPri(i) and N%i is 0:
    			p=0
    			while (N%(i**p) is 0): p+=1
    			d[i]=p-1
    	return d

    def getPrimesList(self):
        return tuple(self.ListPrimes)


