def cnt_subzebroes(n):
        if n > 0:
                cnt = 1
        else:
                cnt = 0
        dict = {}
        dict[n], dict[n + 1] = 0, 0
        last = n - 1
        while last > 0:
                dict[last] = dict[last + 1] + dict[last + 2] + 1
                cnt = cnt + dict[last] + 1
                last -= 1
	return cnt % 1000000007	

