def g(n):
    strNum = str(n)

    ret = 0
    for idx in range(len(strNum)):
        digit = int(strNum[idx])

        for i in range(1, 10):
            leftNum     = int(strNum[:idx]    ) if idx > 0 else 0
            rightNum    = int(strNum[idx + 1:]) if idx + 1 < len(strNum) else 0
            rightDigits = len(strNum) - idx - 1

            if i < digit:
                ret += i * (leftNum  + 1) * (10 ** rightDigits)

            elif i > digit:
                ret += i * (leftNum     ) * (10 ** rightDigits)

            elif i == digit:
                ret += i * (leftNum     ) * (10 ** rightDigits)
                ret += i * (rightNum + 1)

    return ret


def work(a):
    mul = 1
    while mul:
        L = 0
        R = mul * a
        while L < R:
            mid = (L + R) / 2

            if g(mid) >= mul * a:
                R = mid
            else:
                L = mid + 1

        if g(L) == mul * a:
            print 1, L
            break

        mul += 1


