def fastExp(b,n):
    def even(n):
        if n % 2 == 0:
            return 1
        return 0

    if n == 1:
        return b

    a = 1
    if not even(n):
        a = b
        n -= 1

    while n > 1:
        b *= b
        n /= 2
    b *= a
    return b


