def binomialCoef(n, k): 
    C = [[0 for x in range(k+1)] for x in range(n+1)] 
    for i in range(n+1): 
        for j in range(min(i, k)+1): 
            # Base Cases 
            if j == 0 or j == i: 
                C[i][j] = 1
            # Calculate value using previously stored values 
            else: 
                C[i][j] = C[i-1][j-1] + C[i-1][j] 

    return C[n][k] 

def factorial(n): 
    return 1 if (n == 1 or n == 0) else n * factorial(n - 1)  

