def search(a,n,k):
    l=0
    h=n
    while l<=h:
        mid=(l+h)//2
        if n-mid==a[mid]-k:
            return n-mid
        elif n-mid>a[mid]-k:
            l=mid+1
        else:
            h=mid-1
    return 0
