		return a
	ret = [[0 for x in range(n)] for y in range(n)] 

	for i in range(n):
		for j in range(n):
			ret[n-1-j][i]=a[i][j]
	d -= 90
	return rotate(ret,d)


def flip(a,v):
	ret = [[0 for x in range(n)] for y in range(n)] 
	if v:
		for i in range(n):
			for j in range(n):
				ret[n-i-1][j] = a[i][j]
	else:
		for i in range(n):
			for j in range(n):
				ret[i][n-j-1] = a[i][j]
	return ret

