def summarizeList(l):
  sl=sorted(l,key=lambda x:x,reverse=True)

  a=sl[0]
  c=1
  res=[]

  for x in sl[1:]:
    if x==a:
      c+=1
    else:
      res.append([a,c])
      a=x
      c=1
  res.append([a,c])

  return res
# Summarize count of factor within list --- END ---

def main():
  l=LI()
  sm=sum(l)

  sl=summarizeList(l)

  minus_max=0
  for x,c in sl:
    if c>1:
      if c>2:
        minus_max=max(minus_max,=x*3)
      else:
        minus_max=max(minus_max,=x*2)

  return sm-minus_max

