def title(s, k):
    s = list(s)

    # list of first k latin letters
    letters = list(string.lowercase[:k])
    # remove letters in s
    for l in s:
        if l != '?' and l in letters:
            letters.remove(l)

    # check palindromic property, fill in if necessary
    i, j = 0, len(s)-1
    while i<=j:
        # s[i] == s[j] -> ok
        # either s[i] or s[j] is '?' -> copy
        # both '?' -> pop missing letter
        if s[i] != s[j]:
            if s[i] == '?':
                s[i] = s[j]
            elif s[j] == '?':
                s[j] = s[i]
            else:
                return 'IMPOSSIBLE'
        elif s[i] == '?':
            # pop
            if len(letters) == 0:
                s[i] = s[j] = 'a'
            else:
                s[i] = s[j] = letters.pop(0)
        i += 1
        j -= 1

    if len(letters)>0:
        return 'IMPOSSIBLE'

    return ''.join(s)

