    return [a-b for a, b in zip(p1, p2)]

def add(p1, p2):
    return [a+b for a, b in zip(p1, p2)]

def within(p, mid):
    withi = True
    for x in xrange(3):
        if not(p[x]/2.0 <= mid[x] and p[x] >= 0): 
            withi = False
            break
    return withi

def intersect(p1, p2, p3, N):
    denominator = sum([a*b for a, b in zip(N, subtract(p2, p1))])
    if denominator == 0:
    #    print denominator
        return True
    numerator = sum([a*b for a, b in zip(N, subtract(p3, p1))])
    u = numerator*1.0/denominator
    #print u
    p = add(p1, map(lambda(x): x*u, subtract(p2, p1)))
    if u > 0 and u < 1 and within(p, p3):
        return True
    return False

