def really_big(k, s):
    return k - sum([int(x) for x in str(k)]) >= s


def find_big(n, k):
    if not really_big(n, k):
        return 0

    min = n
    while True:
        if really_big(min, k):
            if not really_big(min - 1, k):
                break
            min = min/2
        else:
            min += (n - min)/2

    return n - min + 1

