class CodeforcesTask134BSolution:
    def __init__(self):
        self.result = ''
        self.n = 0

    def read_input(self):
        self.n = int(input())

    def process_task(self):
        go = deque([(1, 1, 0)])
        while go:
            exploring = go.popleft()
            if exploring[0] == self.n or exploring[1] == self.n:
                self.result = str(exploring[2])
                break
            else:
                go.append((exploring[0] + exploring[1], exploring[1], exploring[2] + 1))
                go.append((exploring[0], exploring[1] + exploring[0], exploring[2] + 1))

    def get_result(self):
        return self.result


