disjointSet = [-1] * n
def root(x, level=200):
    if disjointSet[x] < 0:
        return x
    if level < 1:
        while disjointSet[x] >= 0:
            x = disjointSet[x]
        return x
    disjointSet[x] = root(disjointSet[x], level - 1)
    return disjointSet[x]

def join(x, y):
    r1, r2 = root(x), root(y)
    if r1 == r2:
        return
    disjointSet[r2] = r1

