def primes(num):
    prime = [True for i in range(num+1)]
    p = 2
    while (p * p <= num):

        # If prime[p] is not changed, then it is a prime
        if (prime[p] == True):

            # Update all multiples of p
            for i in range(p * 2, num+1, p):
                prime[i] = False
        p += 1
    if(prime[num]== True):
        return 1
    else:
        return 0


