def solve(n,p,a):
    if p is 9:
        if n>=a[9]:
            return 1
        else:
            return 0
    elif p is 0:
        ans=0
        for i in range(a[0],n):
            z=solve(n-i,1,a)
            z*=factorial(n-1)
            z//=factorial(i)
            z//=factorial(n-1-i)
            ans+=z
        return ans
    else:
        ans=0
        for i in range(a[p],n+1):
            z=solve(n-i,p+1,a)
            z*=factorial(n)
            z//=factorial(i)
            z//=factorial(n-i)
            ans+=z
        return ans
