def get_facs(n):
	n1 = n
	facs = []
	i = 2
	while i*i <= n1:
		if n1 % i == 0:
			facs.append([i, 0])
			while n1 % i == 0:
				facs[-1][1] += 1
				n1 /= i
		i += 1
	if n1 > 1:
		facs.append([n1, 1])
	return facs

def sep(x, a, i=1):
	# seperate x into 3 piece x1,x2,x3, x2 <= x3, xi >= 1
	if i==3:
		a[2] = x - a[0] - a[1]
		if a[2] >= 0 and a[2] <= x:
			yield a
		return
	for xi in xrange(0, x+1):
		a[i-1] = xi
		for y in sep(x, a, i+1):
			yield y
		a[i-1] = 0

