from itertools import combinations

class Vector5D:
    def __init__(self, xs):
        if len(xs) != 5:
            raise Exception("pidor")

        self.xs = xs

    def __sub__(self, other):
        return Vector5D([a - b for a, b in zip(self.xs, other.xs)])

    def __abs__(self):
        return sum(x ** 2 for x in self.xs)

    def dot(self, other):
        return sum(a * b for a, b in zip(self.xs, other.xs))

    def __repr__(self):
        return '(%s)' % (' '.join(str(x) for x in self.xs), )

