def is_subsequence(child, parent, i, j, c):
    if i >= len(child) or j >= len(parent):
        return c
    if child[i] == parent[j]:
        return is_subsequence(child, parent, i+1, j+1, c+1)
    else:
        return max(is_subsequence(child, parent, i+1, j, c),is_subsequence(child, parent, i, j+1, c))

