def mul(l,r,mod):
    c = [ (l[0] * r[0] + l[1] * r[1]) % mod,
         (l[0] * r[1] + l[1] * r[3]) % mod,
         (l[2] * r[0] + l[3] * r[2]) % mod,
         (l[2] * r[1] + l[3] * r[3]) % mod ]
    return c

def power(m,n,mod):
    b = [1,0,0,1]
    while n > 0:
        if (n & 1):
            n -= 1
            b = mul(b,m,mod)
        else:
            n >>= 1
            m = mul(m,m,mod)
    return b

def fibs(n,mod):
    if n == 0:
        return (0,1)
    else:
        m = [1,1,1,0]
        return power(m,n,mod)

def fib(n,mod):
    res = fibs(n,mod)
    return res[1]

