mod = 1000000007

def fni(x):
    tmp = mod - 2
    ret = 1
    tt = x
    while (tmp):
        if (tmp & 1):
            ret = (ret * tt) % mod
        tt = (tt * tt) % mod
        tmp >>= 1
    return ret

def solve(f):
    a,b,n = f.read_int_list()
    s = set([a,b])

    c = [1] * (n+1)
    for i in xrange(1, n+1):
        c[i] = (c[i-1] * i) % mod

    ans = 0
    astr, bstr = str(a), str(b)
    lst = [int(''.join(num)) for num in itertools.product([astr,bstr], repeat=int(log10(n))+1)]
    lst += [int(''.join(num)) for num in itertools.product([astr,bstr], repeat=int(log10(n))+2)]

    for i, j in enumerate(xrange(a*n,b*n+1,b-a)):
        if not j in lst: continue
        ans = (ans + c[n] * fni(c[i]) % mod * fni(c[n-i]) % mod) % mod

    print ans


