def binm(n, k,mod): 
    C = [[0 for x in range(k+1)] for x in range(n+1)] 

    # Calculate value of Binomial Coefficient in bottom up manner 
    for i in range(n+1): 
        for j in range(min(i, k)+1): 
            if j == 0 or j == i: 
                C[i][j] = 1

            # Calculate value using previously stored values 
            else: 
                C[i][j] = C[i-1][j-1] + C[i-1][j]
            C[i][j]%=mod

    return C[n][k]%mod
