def f(a,i):
    if i == 0: # base
        if a[i] != 0:
            return 0
        else:
            return 1

    p = i
    t = 1
    while p>=0 and a[p]&t>0:
        if t == 1:
            t = 2
        else:
            t = 1
        p = p-1
    if p<0: return 0
    j = p-1

    p = i
    t = 2
    while p>=0 and a[p]&t>0:
        if t == 1:
            t = 2
        else:
            t = 1
        p = p-1
    if p<0: return 0
    k = p-1

    return 1+min(f(a,j),f(a,k))

