memo = {}

def lookup(i, sol):
    memo[sol] = compute(i, sol)
    return memo[sol]

def compute(i, curr):
    if curr in memo:
        return memo[curr]

    if i == n:
        memo[curr] = len([x for x in curr if x == 'R'])
        return memo[curr]

    if options[i] == 0:
        return lookup(i + 1, curr + 'R')

    if options[i] == 1:
        if i > 0 and curr[i - 1] == 'C':
            return lookup(i + 1, curr + 'R')
        else:
            return lookup(i + 1, curr + 'C')

    if options[i] == 2:
        if i > 0 and curr[i - 1] == 'G':
            return lookup(i + 1, curr + 'R')
        else:
            return lookup(i + 1, curr + 'G')

    if options[i] == 3:
        if i > 0:
            if curr[i - 1] == 'G':
                return lookup(i + 1, curr + 'C')
            elif curr[i - 1] == 'C':
                return lookup(i + 1, curr + 'G')
            else:
                return min(lookup(i + 1, curr + 'G'), lookup(i + 1, curr + 'C'))
        else:
            return min(lookup(i + 1, curr + 'G'), lookup(i + 1, curr + 'C'))

