N = 200001
MOD = 1000000007
fact = [1] * N
inv_fact = [1] * N

def ModExp(a, n):
    ans = 1
    while n:
        if n % 2:
            ans = (ans * a) % MOD
        a = (a * a) % MOD
        n /= 2
    return ans

def ModInverse(a):
    return ModExp(a, MOD - 2)

def PreProcess(n):
    for i in range(1, n + 1):
        fact[i] = (i * fact[i - 1]) % MOD
        inv_fact[i] = (ModInverse(i) * inv_fact[i - 1]) % MOD

def nCr(n, r):
    if n < 0 or r < 0 or n < r:
        return 0
    else:
        return (fact[n] * inv_fact[r] * inv_fact[n - r]) % MOD

def Beggar(m, n):
    if m < 0 or n < 0 or (n == 0 and m != 0):
        return 0
    else:
        if m + n == 0:
            return 1
        else:
            return nCr(m + n - 1, m)

